INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('df69c5d1-aa43-4247-a7b5-9ecfd1c5a72b', 'c3c3c3c3-3030-4000-8000-000000000003', 8, 'Dia 8 — Prioridades', 'Semana 2: Organizar', '{"pch": "Maria escolheu a melhor parte\u2026 Nem tudo que \u00e9 urgente \u00e9 importante.", "verse": "Lc 10,42", "lectio": "Leia Lc 10,38-42. Marta e Maria.", "practice": "Liste suas 5 prioridades. Compare com como gasta seu tempo.", "question": "O que \u00e9 realmente importante na sua vida agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;